INSERT INTO campaigns(id,title,subject,preheader,content_json,status) SELECT 'cmp_music_meditation_starter','Music and Meditation','Musik, Meditation und Begegnungen','Aktuelles aus unserer Gemeinschaft','[{"id":"17306784-9663-4327-a31b-fe3df4153e0a","type":"hero","data":{"eyebrow":"Sahaja Yoga Kultur e.V. · September 2026","title":"Sahaja Yoga · Ein Sommer voller Begegnungen","text":"Gemeinsam erlebt. Voller Vorfreude auf das, was kommt.","pageBackground":"#eef1f6","surfaceBackground":"#ffffff","background":"#17275d","imageUrl":"https://mcusercontent.com/fc12c592c7906c401ea96e6b5/images/7f444944-8ab0-edf8-6e1d-92ad9fe1571e.jpg","opacity":100}},{"id":"85f0c854-8b9c-4f54-b3d0-38b5a205e115","type":"heading","data":{"text":"Hallo liebe Interessenten,","size":30,"color":"#17213f"}},{"id":"969cebab-f2e8-471b-9d85-c85ea65d8b2b","type":"text","data":{"text":"wir blicken auf einen Sommer voller Musik, Meditation und Begegnungen zurück. In dieser Ausgabe findet ihr unsere kommenden Veranstaltungen, regelmäßige Meditationsabende und die schönsten Momente seit dem letzten Newsletter.","color":"#46536b"}},{"id":"774b9b77-9960-4c3f-92e2-188821e5470a","type":"story","data":{"meta":"VORSCHAU · 02. OKTOBER 2026 · MÜNCHEN","title":"The Power of Mental Silence","text":"Ein Abend mit Vortrag, geleiteter Meditation und Musik. Dr. Sergio Elías Hernández und Namastè verbinden ihre Perspektiven auf innere Stille. Alle aktuellen Angaben zur Veranstaltung findet ihr bei der Anmeldung.","imageUrl":"https://mcusercontent.com/fc12c592c7906c401ea96e6b5/images/bd52a0f9-2d54-ea02-bb94-5a2945733150.jpg","alt":"Plakat zur The Power of Mental Silence Tour","layout":"left","url":"https://www.eventbrite.de/e/1997339454074?aff=oddtdtcreator","label":"Kostenloses Ticket reservieren","accent":"#175cdf"}},{"id":"2f4cbc88-1871-49d6-82d9-da8a78290c6f","type":"heading","data":{"text":"Wöchentlich zusammen meditieren","size":28,"color":"#175cdf"}},{"id":"f6c54560-e759-435e-95c4-04ad0b217670","type":"text","data":{"text":"München · Am Lilienberg 2a\nMontag 19:30 · Italienisch\nDienstag 18:30–20:00 · Englisch, außer in den Schulferien\nDonnerstag 19:30 · Offene Gruppe\nFreitag 19:30 · International\nSamstag 18:30 · Mit Anmeldung\n\nBitte überprüft Zeiten und Anmeldewege vor jedem Versand.","color":"#46536b"}},{"id":"5862d93b-ae5c-4c84-8e71-0392cac7fcdd","type":"button","data":{"label":"Aktuelle Termine & Anmeldung","url":"https://www.meetup.com/Free-Meditation-Yoga-Munich/events/","background":"#175cdf","color":"#ffffff"}},{"id":"78394c41-e118-479f-80a8-09d8ce3c369d","type":"heading","data":{"text":"Unser nächstes Wiedersehen","size":28,"color":"#175cdf"}},{"id":"934a506e-9ca0-4af1-820a-d1f3b32e39f6","type":"text","data":{"text":"12.–13. September · Zamanand Festival, München\n16.–18. Oktober · Energetika, Grafing\n\nAktuelle Zeiten und Veranstaltungsdetails vor Veröffentlichung ergänzen.","color":"#46536b"}},{"id":"69a4faca-045b-4f94-9f7b-68f3a52015a5","type":"divider","data":{"color":"#dde3ee"}},{"id":"02122454-0d5b-45b7-b74f-11ae36f11ec9","type":"heading","data":{"text":"Was wir gemeinsam erlebt haben","size":32,"color":"#17213f"}},{"id":"4b7de28e-94bd-4557-87e5-7d3b2edfc60a","type":"story","data":{"meta":"09. Mai 2026 · München","title":"Die Lange Nacht der Musik","text":"Musik, gemeinsame Meditation und Begegnungen prägten diesen Abend im Zentrum. Wir danken den Künstlern und allen helfenden Händen.","imageUrl":"","layout":"left","accent":"#175cdf","url":"","label":"Gesamtes Fotoalbum"}},{"id":"84688e8a-3dcb-4eb1-951e-387c1d39b548","type":"gallery","data":{"imageUrl":"https://mcusercontent.com/fc12c592c7906c401ea96e6b5/images/91446137-52d9-a5d2-7636-b520593e5096.jpg","image2":"https://mcusercontent.com/fc12c592c7906c401ea96e6b5/images/e741fee7-cd73-151a-d93c-10f271ca6081.jpg","image3":"https://mcusercontent.com/fc12c592c7906c401ea96e6b5/_compresseds/d6e85fb4-a11e-319e-1e23-96633a788f32.jpg","imageUrlAlt":"Die Lange Nacht der Musik · Moment 1","image2Alt":"Die Lange Nacht der Musik · Moment 2","image3Alt":"Die Lange Nacht der Musik · Moment 3","url":"https://photos.app.goo.gl/viSGox6yDcQjhDx16","label":"Gesamtes Fotoalbum","background":"#175cdf","color":"#ffffff","radius":4}},{"id":"3d7e4a03-e022-4302-b8d4-71890f362b70","type":"divider","data":{"color":"#e2e7ef"}},{"id":"522d7924-30cd-4227-a089-0fac7d5aade1","type":"story","data":{"meta":"20.–21. Juni 2026 · München","title":"Zamanand Straßenfest","text":"Am Meditationsstand konnten Besucher mitten im Trubel innehalten. Danke an alle, die diese Begegnungen möglich gemacht haben.","imageUrl":"","layout":"right","accent":"#175cdf","url":"","label":"Gesamtes Fotoalbum"}},{"id":"99623d06-cca0-4139-9987-70c34e3189f9","type":"gallery","data":{"imageUrl":"https://mcusercontent.com/fc12c592c7906c401ea96e6b5/images/b5a5d0ad-7b8d-acfb-a32a-e05139d01498.jpg","image2":"https://mcusercontent.com/fc12c592c7906c401ea96e6b5/images/59d2a7c1-3e78-ff2c-d605-37c6ca3cffab.jpg","image3":"https://mcusercontent.com/fc12c592c7906c401ea96e6b5/images/8d63f0a9-0492-a1f6-b736-97a8d60920a3.jpg","imageUrlAlt":"Zamanand Straßenfest · Moment 1","image2Alt":"Zamanand Straßenfest · Moment 2","image3Alt":"Zamanand Straßenfest · Moment 3","url":"https://photos.app.goo.gl/3YBd5QSD2cMkUAeC8","label":"Gesamtes Fotoalbum","background":"#175cdf","color":"#ffffff","radius":4}},{"id":"51c3ff5c-e40a-4387-95f0-8debad94242d","type":"divider","data":{"color":"#e2e7ef"}},{"id":"738d90c6-1ddc-47a4-88fe-d2695232d099","type":"story","data":{"meta":"21. Juni 2026 · München","title":"Internationaler Yogatag","text":"Unser Verein war mit einem Info- und Meditationspavillon sowie einem Beitrag auf der Aktionsbühne vertreten.","imageUrl":"","layout":"left","accent":"#175cdf","url":"","label":"Gesamtes Fotoalbum"}},{"id":"b8d2b4ea-d948-4a47-8a55-89f46b0376fc","type":"gallery","data":{"imageUrl":"https://mcusercontent.com/fc12c592c7906c401ea96e6b5/_compresseds/6678575e-3b15-09f1-28f4-27049f7ad0a6.jpg","image2":"https://mcusercontent.com/fc12c592c7906c401ea96e6b5/_compresseds/6f578c61-3424-44ff-269c-e06d679f2779.jpg","image3":"https://mcusercontent.com/fc12c592c7906c401ea96e6b5/_compresseds/6c8b8354-0968-b452-8358-2a43c7fc2b76.jpg","imageUrlAlt":"Internationaler Yogatag · Moment 1","image2Alt":"Internationaler Yogatag · Moment 2","image3Alt":"Internationaler Yogatag · Moment 3","url":"https://photos.app.goo.gl/Z8xKbtnwFjnxVNqm9","label":"Gesamtes Fotoalbum","background":"#175cdf","color":"#ffffff","radius":4}},{"id":"5fb43613-c1da-4346-b025-bca4c3709ab6","type":"divider","data":{"color":"#e2e7ef"}},{"id":"172137b0-cdd7-4c82-be28-af10c5bb2dce","type":"story","data":{"meta":"04.–05. Juli 2026 · Aalen","title":"Internationales Fest","text":"Gespräche und geleitete Meditationen eröffneten den Besuchern einen persönlichen Zugang zur inneren Stille.","imageUrl":"","layout":"right","accent":"#175cdf","url":"","label":"Gesamtes Fotoalbum"}},{"id":"b45793bc-aac4-4b16-99ba-f61cd59092e1","type":"gallery","data":{"imageUrl":"https://mcusercontent.com/fc12c592c7906c401ea96e6b5/_compresseds/37dde9c6-1630-f60b-38bb-18bdf1282c1c.jpg","image2":"https://mcusercontent.com/fc12c592c7906c401ea96e6b5/_compresseds/2b090ec9-027d-cf49-7115-a9e9ac3c2cb6.jpg","image3":"https://mcusercontent.com/fc12c592c7906c401ea96e6b5/_compresseds/dfab21e3-ce64-1c00-253f-1ad3b6b207cd.jpg","imageUrlAlt":"Internationales Fest · Moment 1","image2Alt":"Internationales Fest · Moment 2","image3Alt":"Internationales Fest · Moment 3","url":"https://photos.app.goo.gl/FNkMdLnkyJf3RwqY8","label":"Gesamtes Fotoalbum","background":"#175cdf","color":"#ffffff","radius":4}},{"id":"2acb9af9-529e-4d42-85f1-f47c2361f0d8","type":"divider","data":{"color":"#e2e7ef"}},{"id":"d43f4163-3751-41a8-87fe-ff21735fac3d","type":"story","data":{"meta":"München · Datum vor Versand prüfen","title":"United Europe Tour","text":"Die Light Route verband Live-Musik und gemeinsame Meditation. Das genaue Veranstaltungsdatum muss vor dem Versand bestätigt werden.","imageUrl":"","layout":"left","accent":"#175cdf","url":"","label":"Gesamtes Fotoalbum"}},{"id":"9ba99e69-f540-49fc-9106-7d87ce49242c","type":"gallery","data":{"imageUrl":"https://mcusercontent.com/fc12c592c7906c401ea96e6b5/_compresseds/def07e59-6b66-9ed2-db6e-30c902641709.jpg","image2":"https://mcusercontent.com/fc12c592c7906c401ea96e6b5/_compresseds/fcac9c55-f116-7d1d-0b9a-1bf3680bbcce.jpg","image3":"https://mcusercontent.com/fc12c592c7906c401ea96e6b5/_compresseds/dcdbd13c-279b-81a3-a94c-cdb9e72aeba0.jpg","imageUrlAlt":"United Europe Tour · Moment 1","image2Alt":"United Europe Tour · Moment 2","image3Alt":"United Europe Tour · Moment 3","url":"https://photos.app.goo.gl/YquBE9w1u7EELgvT7","label":"Gesamtes Fotoalbum","background":"#175cdf","color":"#ffffff","radius":4}},{"id":"6e054992-fd00-4b20-b445-1c31cc9b9dc0","type":"divider","data":{"color":"#e2e7ef"}},{"id":"3bb6e2e1-b0c9-4b91-927f-61f90f68d966","type":"heading","data":{"text":"Aktuelles & Lesenswertes","size":28,"color":"#175cdf"}},{"id":"f033c97d-3183-4ff7-b626-092092699256","type":"text","data":{"text":"Hier ist Platz für einen ausgewählten Artikel, einen Musikbeitrag oder Neuigkeiten aus unserer Gemeinschaft. Kurze Einleitung ergänzen und zum vollständigen Beitrag verlinken.","color":"#46536b"}},{"id":"6170971a-8bfa-4c6a-b8fb-6a091836fb5f","type":"button","data":{"label":"Gemeinsam meditieren · We Meditate","url":"https://wemeditate.com/","background":"#175cdf","color":"#ffffff"}},{"id":"fc3fd59f-680b-4147-9119-196b65af0a23","type":"text","data":{"text":"Mit freundlichen Grüßen & bis bald,\nSahaja Yoga Kultur e.V.","color":"#46536b"}}]','draft' WHERE NOT EXISTS(SELECT 1 FROM campaigns);
